import React, { useState, useEffect, useRef } from 'react'; // Menambahkan useRef
import MaintenanceForm from './components/MaintenanceForm';
import SurvivalChart from './components/SurvivalChart';
import { calculateSurvivalRate, getStatusConfig } from './logic/calculations';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import Papa from 'papaparse'; // Menambahkan PapaParse untuk CSV

// --- BAGIAN FIREBASE START ---
import { initializeApp } from "firebase/app";
import { 
  getFirestore, 
  collection, 
  addDoc, 
  onSnapshot, 
  updateDoc, 
  deleteDoc, 
  doc, 
  query, 
  orderBy 
} from "firebase/firestore";

const firebaseConfig = {
  apiKey: "AIzaSyD4ICTaZqsscro-FQHGtwYnQU9DzdAYdQA",
  authDomain: "maintenance-data-d6d7c.firebaseapp.com",
  projectId: "maintenance-data-d6d7c",
  storageBucket: "maintenance-data-d6d7c.firebasestorage.app",
  messagingSenderId: "622641610666",
  appId: "1:622641610666:web:7ddc9a9114a197e47a35d3",
  measurementId: "G-HHC2YZLX6J"
};

const app = initializeApp(firebaseConfig);
const db = getFirestore(app);
// --- BAGIAN FIREBASE END ---

function App() {
  const [allSites, setAllSites] = useState([]);
  const [activeSiteIndex, setActiveSiteIndex] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [viewMode, setViewMode] = useState('single');
  const fileInputRef = useRef(null); // Ref untuk input file CSV

  // --- LOGIKA PRIVATE ACCESS START ---
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [inputPass, setInputPass] = useState("");
  const SECRET_PASSWORD = "Marinesolution20"; 

  const handleLogin = (e) => {
    e.preventDefault();
    if (inputPass === SECRET_PASSWORD) {
      setIsAuthenticated(true);
    } else {
      alert("Password Salah! Akses Ditolak.");
    }
  };

  const handleLogout = () => {
    if(window.confirm("Keluar dari sistem? Dashboard akan dikunci kembali.")) {
      setIsAuthenticated(false);
      setInputPass("");
    }
  };
  // --- LOGIKA PRIVATE ACCESS END ---

  // --- LOGIKA CSV START ---
  const exportCSV = () => {
    if (allSites.length === 0) return alert("Tidak ada data untuk di-export.");
    
    // Mapping data agar header CSV rapi
    const dataForCsv = allSites.map(site => ({
      SiteName: site.siteName,
      InitialFragments: site.InitialFragments,
      ReefStars: site.reefStars,
      Notes: site.notes,
      Date_W2: site.d2, Week2_Perc: site.chartRates[0],
      Date_W4: site.d4, Week4_Perc: site.chartRates[1],
      Date_W6: site.d6, Week6_Perc: site.chartRates[2],
      Date_W8: site.d8, Week8_Perc: site.chartRates[3],
      Date_W12: site.d12, Week12_Perc: site.chartRates[4]
    }));

    const csv = Papa.unparse(dataForCsv);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `Coral_Data_${new Date().toISOString().slice(0,10)}.csv`);
    link.click();
  };

  const importCSV = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: async (results) => {
        if (window.confirm(`Import ${results.data.length} data site ke database cloud?`)) {
          try {
            for (const row of results.data) {
              const initial = parseFloat(row.InitialFragments);
              const rates = [
                parseFloat(row.Week2_Perc) || null,
                parseFloat(row.Week4_Perc) || null,
                parseFloat(row.Week6_Perc) || null,
                parseFloat(row.Week8_Perc) || null,
                parseFloat(row.Week12_Perc) || null
              ];
              const validRates = rates.filter(r => r !== null);
              const currentSR = validRates.length > 0 ? validRates[validRates.length - 1] : 0;

              await addDoc(collection(db, "sites"), {
                siteName: row.SiteName,
                InitialFragments: row.InitialFragments,
                reefStars: row.ReefStars,
                notes: row.Notes,
                d2: row.Date_W2, d4: row.Date_W4, d6: row.Date_W6, d8: row.Date_W8, d12: row.Date_W12,
                chartRates: rates,
                currentSR: currentSR
              });
            }
            alert("Berhasil mengimpor data!");
          } catch (err) {
            alert("Error saat simpan data: " + err.message);
          }
        }
      }
    });
  };
  // --- LOGIKA CSV END ---

  useEffect(() => {
    const q = query(collection(db, "sites"), orderBy("siteName", "asc"));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const sitesArr = [];
      querySnapshot.forEach((doc) => {
        sitesArr.push({ ...doc.data(), id: doc.id });
      });
      setAllSites(sitesArr);
    });
    return () => unsubscribe();
  }, []);

  const handleDataSubmit = async (formData) => {
    const initial = parseFloat(formData.InitialFragments);
    const rates = ['m2', 'm4', 'm6', 'm8', 'm12'].map(w => calculateSurvivalRate(initial, formData[w]));
    const validRates = rates.filter(r => r !== null);
    const currentSR = validRates.length > 0 ? validRates[validRates.length - 1] : 0;
    const siteData = { ...formData, chartRates: rates, currentSR };

    try {
      if (activeSiteIndex !== null && allSites[activeSiteIndex].id) {
        const siteDoc = doc(db, "sites", allSites[activeSiteIndex].id);
        await updateDoc(siteDoc, siteData);
      } else {
        await addDoc(collection(db, "sites"), siteData);
      }
      setIsEditing(false);
      setActiveSiteIndex(null);
    } catch (e) {
      alert("Gagal menyimpan ke Cloud: " + e.message);
    }
  };

  const handleDeleteSite = async (index) => {
    const site = allSites[index];
    if (window.confirm(`DELETE SITE "${site.siteName}" secara permanen?`)) {
      try {
        await deleteDoc(doc(db, "sites", site.id));
        setActiveSiteIndex(null);
      } catch (e) {
        alert("Gagal menghapus: " + e.message);
      }
    }
  };

  const exportPDF = (elementId, title) => {
    const input = document.getElementById(elementId);
    html2canvas(input, { scale: 2 }).then(canvas => {
      const img = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      pdf.text(title, 15, 15);
      pdf.addImage(img, 'PNG', 10, 25, 190, (canvas.height * 190) / canvas.width);
      pdf.save(`${title}.pdf`);
    });
  };

  if (!isAuthenticated) {
    return (
      <div style={styles.loginOverlay}>
        <div style={styles.loginCard}>
          <h2 style={{ color: '#3498db', marginBottom: '10px' }}>🔐 Private Access</h2>
          <p style={{ color: '#7f8c8d', marginBottom: '20px', fontSize: '14px' }}>Marine Sustainable Solution</p>
          <form onSubmit={handleLogin}>
            <input 
              type="password" 
              placeholder="Enter Password"
              style={styles.loginInput}
              onChange={(e) => setInputPass(e.target.value)}
            />
            <button type="submit" style={styles.loginBtn}>Open Dashboard</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '20px', fontFamily: 'sans-serif', color: '#2c3e50' }}>
      <header style={styles.header}>
        <div>
          <h1 style={{margin:0}}>Maintenance Data</h1>
          <div style={{marginTop: '10px', display: 'flex', gap: '8px'}}>
            <button onClick={() => setViewMode('single')} style={viewMode === 'single' ? styles.activeTab : styles.tab}>all sites</button>
            <button onClick={() => setViewMode('all')} style={viewMode === 'all' ? styles.activeTab : styles.tab}>Chart all sites</button>
            {/* Tombol CSV */}
            <button onClick={exportCSV} style={styles.csvBtn}>Export CSV</button>
            <button onClick={() => fileInputRef.current.click()} style={styles.csvBtn}>Import CSV</button>
            <input type="file" ref={fileInputRef} onChange={importCSV} accept=".csv" style={{display:'none'}} />
          </div>
        </div>
        <div style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
          <button onClick={() => { setActiveSiteIndex(null); setIsEditing(true); setViewMode('single'); }} style={styles.newBtn}>+ ADD SITE</button>
          <button onClick={handleLogout} style={styles.logoutBtn}>Logout</button>
        </div>
      </header>

      <div style={{ display: 'grid', gridTemplateColumns: '280px 1fr', gap: '20px' }}>
        <aside style={styles.sidebar}>
          <h3>Site</h3>
          {allSites.length === 0 && <small>There is no data in the cloud database yet</small>}
          {allSites.map((site, i) => (
            <div key={i} onClick={() => { setActiveSiteIndex(i); setIsEditing(false); setViewMode('single'); }} 
                 style={{ ...styles.siteItem, background: (activeSiteIndex === i && viewMode==='single') ? '#fff' : 'transparent', borderLeft: activeSiteIndex === i ? '5px solid #3498db' : 'none' }}>
              <strong>{site.siteName}</strong><br/><small>Status: {site.currentSR}%</small>
            </div>
          ))}
        </aside>

        <main>
          {viewMode === 'all' ? (
            <div id="global-report" style={styles.card}>
              <h2>Perbandingan Global</h2>
              <div style={{ height: '400px', margin: '20px 0' }}>
                <SurvivalChart isGlobal={true} allSites={allSites} />
              </div>
              <button onClick={() => exportPDF('global-report', 'Ringkasan_Proyek')} style={styles.pdfBtn}> Export Data</button>
            </div>
          ) : (
            isEditing || (activeSiteIndex === null && allSites.length === 0) ? (
              <div style={styles.card}>
                <h2>{activeSiteIndex !== null ? `Edit Site` : 'Add Your Sites'}</h2>
                <MaintenanceForm onDataSubmit={handleDataSubmit} editData={activeSiteIndex !== null ? allSites[activeSiteIndex] : null} />
              </div>
            ) : activeSiteIndex !== null ? (
              <div id="report-area" style={styles.card}>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <h2>{allSites[activeSiteIndex].siteName}</h2>
                  <div>
                    <button onClick={() => setIsEditing(true)} style={styles.editBtn}>Edit Data</button>
                    <button onClick={() => exportPDF('report-area', `Laporan_${allSites[activeSiteIndex].siteName}`)} style={styles.pdfBtn}>Export PDF</button>
                  </div>
                </div>

                <div style={styles.gridStats}>
                  <div style={styles.statCard}><strong>Initial Fragments </strong><br/>{allSites[activeSiteIndex].InitialFragments}</div>
                  <div style={styles.statCard}><strong>Reef Stars</strong><br/>{allSites[activeSiteIndex].reefStars || '-'}</div>
                  <div style={{ ...styles.statCard, borderTop: `4px solid ${getStatusConfig(allSites[activeSiteIndex].currentSR).color}` }}>
                    <strong>Percentage</strong><br/>
                    <span style={{ color: getStatusConfig(allSites[activeSiteIndex].currentSR).color, fontWeight: 'bold' }}>{getStatusConfig(allSites[activeSiteIndex].currentSR).label} ({allSites[activeSiteIndex].currentSR}%)</span>
                  </div>
                </div>

                <div style={{ height: '300px', margin: '25px 0' }}>
                  <SurvivalChart dataLogs={allSites[activeSiteIndex].chartRates} />
                </div>

                <p style={{fontWeight:'bold', marginBottom:'10px'}}>Maintenance Time:</p>
                <div style={styles.monitorGrid}>
                    {['2','4','6','8','12'].map((w, idx) => {
                        const rate = allSites[activeSiteIndex].chartRates[idx];
                        const cfg = getStatusConfig(rate);
                        return (
                            <div key={w} style={{...styles.monitorCard, borderTop: `4px solid ${rate !== null ? cfg.color : '#eee'}`}}>
                                <small style={{fontWeight:'bold'}}>Week {w}</small>
                                <div style={{fontSize:'10px', color:'#7f8c8d', margin:'4px 0'}}>{allSites[activeSiteIndex][`d${w}`] || 'No Date'}</div>
                                <div style={{fontSize:'18px', fontWeight:'bold'}}>{rate !== null ? `${rate}%` : '-'}</div>
                            </div>
                        );
                    })}
                </div>

                <div style={styles.notesSection}><strong>Notes:</strong><p>{allSites[activeSiteIndex].notes || "No records."}</p></div>

                <div style={{textAlign:'right', marginTop:'25px'}}>
                    <button onClick={() => handleDeleteSite(activeSiteIndex)} style={styles.deleteBtn}>Delete Site</button>
                </div>
              </div>
            ) : (
                <div style={styles.card}>Please select a site.</div>
            )
          )}
        </main>
      </div>
    </div>
  );
}

const styles = {
  header: { display: 'flex', justifyContent: 'space-between', borderBottom: '2px solid #eee', paddingBottom: '20px', marginBottom: '20px' },
  newBtn: { padding: '10px 20px', backgroundColor: '#2ecc71', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', fontWeight: 'bold' },
  logoutBtn: { padding: '8px 15px', backgroundColor: '#95a5a6', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', fontSize: '12px' },
  sidebar: { background: '#f8f9fa', padding: '15px', borderRadius: '10px', minHeight: '400px' },
  siteItem: { padding: '12px', marginBottom: '8px', borderRadius: '8px', cursor: 'pointer', transition: '0.3s', border: '1px solid #eee' },
  card: { background: '#fff', padding: '25px', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.08)' },
  gridStats: { display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '15px' },
  statCard: { padding: '15px', background: '#f9f9f9', borderRadius: '8px', textAlign: 'center', border: '1px solid #eee' },
  monitorGrid: { display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '10px' },
  monitorCard: { padding: '12px', background: '#fdfdfd', borderRadius: '8px', textAlign: 'center', border: '1px solid #eee' },
  notesSection: { marginTop: '20px', padding: '15px', background: '#fdfdfd', border: '1px solid #eee', borderRadius: '8px' },
  editBtn: { background: '#f39c12', color: '#fff', border: 'none', padding: '8px 15px', borderRadius: '5px', cursor: 'pointer', marginRight: '5px' },
  pdfBtn: { background: '#e74c3c', color: '#fff', border: 'none', padding: '8px 15px', borderRadius: '5px', cursor: 'pointer' },
  deleteBtn: { background: 'none', border: '1px solid #e74c3c', color: '#e74c3c', padding: '5px 12px', borderRadius: '5px', cursor: 'pointer', fontSize: '12px' },
  tab: { padding: '8px 15px', border: 'none', background: '#eee', cursor: 'pointer', borderRadius: '5px 5px 0 0', marginRight: '5px' },
  activeTab: { padding: '8px 15px', border: 'none', background: '#3498db', color: 'white', cursor: 'pointer', borderRadius: '5px 5px 0 0', marginRight: '5px' },
  csvBtn: { padding: '8px 15px', border: 'none', background: '#9b59b6', color: 'white', cursor: 'pointer', borderRadius: '5px', fontSize: '12px' }, // Style CSV baru
  loginOverlay: { display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100vh', background: '#f0f2f5', fontFamily: 'sans-serif' },
  loginCard: { background: '#fff', padding: '40px', borderRadius: '15px', boxShadow: '0 8px 30px rgba(0,0,0,0.1)', textAlign: 'center', width: '350px' },
  loginInput: { padding: '12px', width: '100%', marginBottom: '15px', borderRadius: '8px', border: '1px solid #ddd', boxSizing: 'border-box' },
  loginBtn: { padding: '12px', width: '100%', background: '#3498db', color: '#fff', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }
};

export default App;